// Ambient declarations for image assets imported by transitively type-checked
// login-resources components reused by the guest meeting UI.
declare module '*.png' {
  const content: string
  export default content
}
declare module '*.avif' {
  const content: string
  export default content
}
declare module '*.webp' {
  const content: string
  export default content
}
declare module '*.jpg' {
  const content: string
  export default content
}
